-- Manual spot-check seed for local dev / tests: one match in progress,
-- 6 players split 3-and-3, using the same task_ids seeded in
-- CodeService's data.sql so both seed sets line up.
\c game_service

ON CONFLICT (game_id) DO NOTHING;

